    lines += 1.00 * smoothstep(max(1.8 * ds, 0.14), 0.0, abs(s - 0.90));
    lines += 0.70 * smoothstep(w, 0.0, abs(s - 0.50));
    lines += 0.85 * smoothstep(w, 0.0, abs(s - 0.08));
