    dark += smoothstep(w * 1.3, 0.0, abs(s - 0.70));
    dark += smoothstep(w * 1.1, 0.0, abs(s - 0.29));
    return vec4(body, clamp(lines, 0.0, 1.0), zp, clamp(dark, 0.0, 1.0));
